UPDATE study_metrics SET extra = jsonb_set(jsonb_set(jsonb_set(jsonb_set(COALESCE(extra, '{}'::jsonb) || '{"d1":"2026-10-19","dias_ciclo":52,"regimen":"MANTENIMIENTO_2027-1 v6.21 (52 d) + INTENSIVA v6.02 (núcleo 4-ene → 5-mar + cola anclada)","exam_date":"2027-03-14","examen_target":"2027-03-14 (dom · PROVISIONAL v6.00-v6.02: «más o menos el 14»; 6/6 ENCAPS previos en domingo; se fija con la convocatoria; regla convocatoria = examen − 25 d → sin convocatoria al mié 17-feb se descarta el 14-mar y se pasa al escenario siguiente)","backup":"study_schedule_bk_v602_20261017","dias_a_examen_nota":"vivo: la app (diasAExamenDe) y el daemon calculan exam_date − hoy (Lima); study_metrics.dias_a_examen es solo el fallback estático. v6.02 (2026-10-17): exam_date = 2027-03-14 PROVISIONAL.","corrimiento":{"version":"v6.02","fecha":"2026-10-17","d1_previo":"2026-10-12","d1":"2026-10-19","perdidos":["2026-10-12","2026-10-13","2026-10-14","2026-10-15","2026-10-16"],"regla_fechas_v6":"F1 anclada (la intensiva ENCAPS empieza el 4-ene): 52 hábiles; los hitos F1 NO se desplazan (UWSA1 D1 · NBME 25 D10 · 26 D25 · 27 D40 · NBME 28 = última sesión de F1, mié 30-dic); las 6 filas de temario que no caben (v5.20 D52-D54, D56, D57 Heme/Onco + D79 bioestadística) pasan al tramo 2 como filas desplazadas con su dOrig; examen Step 1 sin cambio","regla_encaps":"F1 ENCAPS rígida por slots (dia 1-52); 8 pendiente(s) F1 que no caben (6 banqueo1h + 2 mini-sim; por corrimiento: v6.01 3 + v6.02 5) → reposición EXPLÍCITA en el carril B 16:15; nada se descarta ni se absorbe (0 mini-sims F1 absorbidos); intensiva renumerada con las mismas fechas","f1":"dia 1-52 (2026-10-19 → 2026-12-30); la F1 no se alarga","intensiva_renumerada":"dia 53-102 (mismas fechas 2027-01-04 → 2027-03-12)","carril_b_dia_mant":"etiqueta de ORIGEN 61-92 (v5.20), sin cambio","historial":["v6.01 2026-10-10: D1 2026-10-07 → 2026-10-12","v6.02 2026-10-17: D1 2026-10-12 → 2026-10-19"],"pendientes_f1":[{"corrimiento":"v6.01","tipo":"banque